  ('8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कवि ने रानी के बलिदान को 'स्वतंत्रता अविनाशी' जगाने वाला क्यों कहा है?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$'होवे चुप इतिहास, लगे सच्चाई को चाहे फाँसी' - इन पंक्तियों के माध्यम से कवि क्या संदेश देना चाहते हैं?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$'तेरा स्मारक तू ही होगी, तू खुद अमिट निशानी थी' - इस पंक्ति का भावार्थ विस्तार से लिखिए।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कविता में रानी लक्ष्मीबाई के शौर्य और पराक्रम का चित्रण किस प्रकार किया गया है?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true);
INSERT INTO public.question_bank (id, institution_id, subject_id, topic_id, grade_level_id, class_group_id, question_text, question_type, options, correct_answer, marks, difficulty_level, tags, source, created_by, is_approved, parent_question_id, sub_question_count, sequence_order) VALUES
  ('74476da8-7d56-4df5-bc9e-e1150db9d7ca', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सुभद्रा कुमारी चौहान का जन्म 1904 में उत्तर प्रदेश के प्रयागराज में हुआ था। उनकी आरंभिक शिक्षा प्रयागराज में हुई। अपने समय की प्रसिद्ध रचनाकार होने के साथ-साथ वह एक स्वतंत्रता सेनानी भी थीं जिसके कारण उन्हें दो बार जेल भी जाना पड़ा था। उन्होंने अपनी कविताओं के माध्यम से जनमानस में राष्ट्रीय चेतना जगाई। उनके लेखन में देशप्रेम, स्त्री-केंद्रित विषयों और स्वाधीनता संग्राम के प्रति गहन प्रतिबद्धता दिखाई देती है। उनकी भाषा की सहजता ने उनकी रचनाओं को व्यापक लोकप्रियता दिलाई। उनकी कुछ प्रमुख रचनाएँ हैं— मुकुल, त्रिधारा (कविता संग्रह), बिखरे मोती, उन्मादिनी, सीधे-सादे चित्र (कहानी संग्रह), कदंब का पेड़, सभा का खेल (बाल साहित्य)। सुभद्रा कुमारी चौहान को उनके कविता संग्रह मुकुल तथा कहानी संग्रह बिखरे मोती के लिए दो बार ‘सेकसरिया पुरस्कार’ से सम्मानित किया गया। सन् 1948 में उनकी आकस्मिक मृत्यु हो गई। भारतीय डाक विभाग ने उनके सम्मान में एक डाक टिकट भी जारी किया। ‘झाँसी की रानी’ सुभद्रा कुमारी चौहान की बहुत प्रसिद्ध कविता है। यह कविता 1857 के स्वतंत्रता संग्राम की पृष्ठभूमि पर लिखी गई है। 1857 की क्रांति भारतीय स्वतंत्रता संग्राम का अविस्मरणीय अध्याय है। यह कविता रानी लक्ष्मीबाई के जीवन-वृत्त, उनके संघर्ष और विद्रोह से हमारा ओजपूर्ण साक्षात्कार कराती है। यह कविता वीरता, उत्साह और देशप्रेम की भावना से ओत-प्रोत है। यह पाठकों में जोश और साहस का संचार करती है तथा अपने देश के प्रति गर्व एवं स्वतंत्रता के लिए समर्पण की भावना जगाती है। कविता की कथात्मक शैली और गेयता इसे और अधिक जीवंत एवं प्रभावशाली बनाती है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('73457580-b98d-4fe0-b277-3c1c7b83ec20', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सुभद्रा कुमारी चौहान का जन्म 1904 में उत्तर प्रदेश के प्रयागराज में हुआ था। उनकी आरंभिक शिक्षा प्रयागराज में हुई। अपने समय की प्रसिद्ध रचनाकार होने के साथ-साथ वह एक स्वतंत्रता सेनानी भी थीं जिसके कारण उन्हें दो बार जेल भी जाना पड़ा था। उन्होंने अपनी कविताओं के माध्यम से जनमानस में राष्ट्रीय चेतना जगाई। उनके लेखन में देशप्रेम, स्त्री-केंद्रित विषयों और स्वाधीनता संग्राम के प्रति गहन प्रतिबद्धता दिखाई देती है। उनकी भाषा की सहजता ने उनकी रचनाओं को व्यापक लोकप्रियता दिलाई। उनकी कुछ प्रमुख रचनाएँ हैं— मुकुल, त्रिधारा (कविता संग्रह), बिखरे मोती, उन्मादिनी, सीधे-सादे चित्र (कहानी संग्रह), कदंब का पेड़, सभा का खेल (बाल साहित्य)। सुभद्रा कुमारी चौहान को उनके कविता संग्रह मुकुल तथा कहानी संग्रह बिखरे मोती के लिए दो बार ‘सेकसरिया पुरस्कार’ से सम्मानित किया गया। सन् 1948 में उनकी आकस्मिक मृत्यु हो गई। भारतीय डाक विभाग ने उनके सम्मान में एक डाक टिकट भी जारी किया। ‘झाँसी की रानी’ सुभद्रा कुमारी चौहान की बहुत प्रसिद्ध कविता है। यह कविता 1857 के स्वतंत्रता संग्राम की पृष्ठभूमि पर लिखी गई है। 1857 की क्रांति भारतीय स्वतंत्रता संग्राम का अविस्मरणीय अध्याय है। यह कविता रानी लक्ष्मीबाई के जीवन-वृत्त, उनके संघर्ष और विद्रोह से हमारा ओजपूर्ण साक्षात्कार कराती है। यह कविता वीरता, उत्साह और देशप्रेम की भावना से ओत-प्रोत है। यह पाठकों में जोश और साहस का संचार करती है तथा अपने देश के प्रति गर्व एवं स्वतंत्रता के लिए समर्पण की भावना जगाती है। कविता की कथात्मक शैली और गेयता इसे और अधिक जीवंत एवं प्रभावशाली बनाती है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
