  ('f26048c5-e881-4d88-be67-bdfa7d1b5154', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$काानाा और मंदराा सखियााँ राानी के सँग आई थीं, युद्ध क्ेत्र में उन दोनों ने भाारी माार मचााई थी, पर, पीछे ह्ू रोज आ गयाा, हााय! घिरी अब राानी थी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('9d05309d-3b6e-4d20-8dc5-1d796c9029d4', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$तो भी राानी माार-काटकर चलती बनी सैन्य के पाार, किंतु साामने नाालाा आयाा, थाा यह संकट विषम अपाार, घोड़़ाा अड़़ाा, नयाा घोड़़ाा थाा, इतने में आ गए सवाार,$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('0615b5cb-29e5-4b1a-9acc-1d80abd563ac', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$राानी एक, शत्रु बहुतेरे, होने लगे वाार पर वाार, घाायल होकर गिरी सिंहनी उसे वीर-गति पाानी थी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('2d5925cc-09bc-44e7-b190-55ad9bea4b42', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$बुंदेले हरबोलों के मुँह हमने सुनी कहाानी थी। खूब लड़़ी मर््दानी वह तो झााँसी वााली राानी थी॥$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('6e6721fc-5c47-4f10-8635-6efd428c11bf', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$राानी गई सिधाार, चिताा अब उसकी दिव्य सवाारी थी, मिलाा तेज से तेज, तेज की वह सच्ची अधिकाारी थी,$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('f3ed30d2-45e5-4a6a-991f-509fd0f4f8b7', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अभी उम्र कुल तेइस की थी, मनुज नहीं अवताारी थी, हमको जीवित करने आई बन स्वतंत्रताा नाारी थी,$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('3bda548e-8c44-461d-bdf1-f78199e996e9', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दिखाा गई पथ, सिखाा गई हमको जो सीख सिखाानी थी। बुंदेले हरबोलों के मुँह हमने सुनी कहाानी थी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('611ffc83-61b4-4a91-88be-91fc73f279ef', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$खूब लड़़ी मर््दानी वह तो झााँसी वााली राानी थी॥ जााओ राानी यााद रखेंगे हम कृतज्ञ भाारत वाासी,$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('993e4e74-f303-4fe4-bdca-5777f048f94a', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यह तेराा बलिदाान जगाावेगाा स्वतंत्रताा अविनााशी, होवे चुप इतिहाास, लगे सच््चचााई को चााहे फााँसी,$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('78fd9a9b-3e2d-4e04-a472-c1ef742de1c3', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हो मदमााती विजय, मिटाा दे गोलों से चााहे झााँसी, तेराा स््ममाारक तू ही होगी, तू खुद अमिट निशाानी थी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('f84360be-dd25-455d-8347-0dc1b916beef', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$राानी गई सिधाार, चिताा अब उसकी दिव्य सवाारी थी, मिलाा तेज से तेज, तेज की वह सच्ची अधिकाारी थी, अभी उम्र कुल तेइस की थी, मनुज नहीं अवताारी थी,$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('39479168-53bb-4094-875b-a20853840be9', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हमको जीवित करने आई बन स्वतंत्रताा नाारी थी, दिखाा गई पथ, सिखाा गई हमको जो सीख सिखाानी थी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('c0f313a3-736d-4953-a884-4be3a72b7057', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जााओ राानी यााद रखेंगे हम कृतज्ञ भाारत वाासी, यह तेराा बलिदाान जगाावेगाा स्वतंत्रताा अविनााशी,$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('71852d11-6a30-4338-902b-73ac27a8d8f1', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सुभद्रा कुमारी चौहान का जन्म 1904 में उत्तर प्रदेश के प्रयागराज में हुआ था। उनकी आरंभिक शिक्षा प्रयागराज में हुई। अपने समय की प्रसिद्ध रचनाकार होने के साथ-साथ वह एक स्वतंत्रता सेनानी भी थीं जिसके कारण उन्हें दो बार जेल भी जाना पड़ा था। उन्होंने अपनी कविताओं के माध्यम से जनमानस में राष्ट्रीय चेतना जगाई। उनके लेखन में देशप्रेम, स्त्री-केंद्रित विषयों और स्वाधीनता संग्राम के प्रति गहन प्रतिबद्धता दिखाई देती है। उनकी भाषा की सहजता ने उनकी रचनाओं को व्यापक लोकप्रियता दिलाई। उनकी कुछ प्रमुख रचनाएँ हैं— मुकुल, त्रिधारा (कविता संग्रह), बिखरे मोती, उन्मादिनी, सीधे-सादे चित्र (कहानी संग्रह), कदंब का पेड़, सभा का खेल (बाल साहित्य)। सुभद्रा कुमारी चौहान को उनके कविता संग्रह मुकुल तथा कहानी संग्रह बिखरे मोती के लिए दो बार ‘सेकसरिया पुरस्कार’ से सम्मानित किया गया। सन् 1948 में उनकी आकस्मिक मृत्यु हो गई। भारतीय डाक विभाग ने उनके सम्मान में एक डाक टिकट भी जारी किया। ‘झाँसी की रानी’ सुभद्रा कुमारी चौहान की बहुत प्रसिद्ध कविता है। यह कविता 1857 के स्वतंत्रता संग्राम की पृष्ठभूमि पर लिखी गई है। 1857 की क्रांति भारतीय स्वतंत्रता संग्राम का अविस्मरणीय अध्याय है। यह कविता रानी लक्ष्मीबाई के जीवन-वृत्त, उनके संघर्ष और विद्रोह से हमारा ओजपूर्ण साक्षात्कार कराती है। यह कविता वीरता, उत्साह और देशप्रेम की भावना से ओत-प्रोत है। यह पाठकों में जोश और साहस का संचार करती है तथा अपने देश के प्रति गर्व एवं स्वतंत्रता के लिए समर्पण की भावना जगाती है। कविता की कथात्मक शैली और गेयता इसे और अधिक जीवंत एवं प्रभावशाली बनाती है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
