  ('b44448a2-a529-4813-a102-6728cae7bfae', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सिंहाासन हिल उठे, रााजवंशों ने भृकुटी ताानी थी, बूढ़े भाारत में भी आई फिर से नई जवाानी थी, गुमी हुई आजाादी की कीमत सबने पहचाानी थी, दूर फि़रंगी को करने की सबने मन में ठाानी थी, चमक उठी सन् सत्ताावन में वह तलवाार पुराानी थी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ca9bad01-f37c-44eb-bc71-74fcde37f9f8', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$बुंदेले हरबोलों के मुँह हमने सुनी कहाानी थी। खूब लड़़ी मर््दानी वह तो झााँसी वााली राानी थी॥$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('51ddb797-7792-454d-9d2b-2ccdaf00629b', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$काानपूर के नाानाा की मुँहबोली बहन ‘छबीली’ थी, लक्मीबााई नााम, पिताा की वह संताान अकेली थी, नाानाा के सँग पढ़ती थी वह, नाानाा के सँग खेली थी, बरछी, ढााल, कृपााण, कटाारी उसकी यही सहेली थी, वीर शिवााजी की गााथााएँ उसको यााद ज़बाानी थीं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('83f8826c-b44b-4001-bab4-974429494a56', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लक्मी थी याा दुर््गगाा थी वह स्वयं वीरताा की अवताार, देख मरााठे पुलकित होते उसकी तलवारोों के वाार, नकली युद्ध, व्यूह की रचनाा और खेलनाा खूब शिकाार, सैन्य घेरनाा, दुर््ग तोड़नाा, ये थे उसके प्रिय खिलवाार।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('046afefd-0112-4279-a8ed-797efbfe9690', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सिंहाासन हिल उठे, रााजवंशों ने भृकुटी ताानी थी, बूढ़े भाारत में भी आई फिर से नई जवाानी थी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('28831c63-de28-4cb9-ae45-42a53cc34f11', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$गुमी हुई आजाादी की कीमत सबने पहचाानी थी, दूर फि़रंगी को करने की सबने मन में ठाानी थी, चमक उठी सन् सत्ताावन में वह तलवाार पुराानी थी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
