  ('5b62bd22-f632-4853-81e1-37682354f6ba', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$बुझाा दीप झााँसी काा तब डलहौजी मन में हरषाायाा,रााज्य हड़प करने काा उसने यह अच््छछाा अवसर पाायाा,फौरन फौजें भेज दुर््ग पर अपनाा झंडाा फहराायाा,लाावाारिस काा वाारिस बनकर ब्रिटिश रााज्य झााँसी आयाा,अश्ुपूर््ण राानी ने देखाा झााँसी हुई बिराानी थी।बुंदेले हरबोलों के मुँह हमने सुनी कहाानी थी।खूब लड़़ी मर््दानी वह तो झााँसी वााली राानी थी॥$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('8e0d4be2-bd77-4259-b8b3-0a573b2546ed', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अनुनय-विनय नहीं सुनताा है, विकट फि़रंगी की माायाा,व््ययाापाारी बन दयाा चााहताा थाा जब यह भाारत आयाा,डलहौजी ने पैर पसाारे अब तो पलट गई काायाा,रााजााओं नव््ववाबों को भी उसने पैरों ठुकराायाा,राानी दाासी बनी, बनी यह दाासी अब महराानी थी।बुंदेले हरबोलों के मुँह हमने सुनी कहाानी थी।खूब लड़़ी मर््दानी वह तो झााँसी वााली राानी थी॥$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('7211201b-383c-46fb-bae0-c5a553e86f09', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$छिनी रााजधाानी देहली की, लियाा लखनऊ बातोों-बाात,कैद पेशवाा थाा बिठूर में, हुआ नाागपुर काा भी घाात,उदैपूर, तंजोर, सतााराा, करनाटक की कौन बिसाात,जब कि सिंध, पंजााब, ब्रह्म पर अभी हुआ थाा वज्र-निपाात,बंगााले, मद्रास आदि की भी तो यही कहाानी थी।बुंदेले हरबोलों के मुँह हमने सुनी कहाानी थी।खूब लड़़ी मर््दानी वह तो झााँसी वााली राानी थी॥$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
