  ('0e34e57d-3fc2-4bdf-80ef-f2cb5ee7ef67', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$रानी रोईं रनिवासों में बेगम ग़म से थीं बेज़ार उनके गहने-कपड़े बिकते थे कलकत्ते के बाज़ार, सरे-आम नीलाम छापते थे अंग्रेजों के अख़बार, 'नागपूर के ज़ेवर ले लो' 'लखनऊ के लो नौलख हार', यों परदे की इज़्ज़त पर- देशी के हाथ बिकानी थी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
