  ('4786d65b-80eb-400b-a338-91bb23fbaf5c', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$रानी बढ़ी काललपी आई, कर सौ मीलल निरंतर पार घोड़ा थक कर गिरा भूमि पर, गया स््वर््ग तत््ककालल सिधार,$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
