  ('0094ddc1-f317-4979-88f2-c8d9c7c9b761', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इस स््वतंत्रता-महायज्ञ में कई ववीरववर आए काम नाना धुंधूपंत, ताँतिया, चतुर अज़ीमुल््ला सरनाम, अहमद शाह मौलववी, ठाकुर कुँववरसिंह सैनिक अभिराम, भारत के इतिहास-गगन में अमर रहेंगे जिनके नाम,$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ffa1e559-c2fe-413e-b138-84c15b4417a0', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लेकिन आज जुर्म कहललाती उनकी जो कुरबानी थी। बुंदेलले हरबालोों के मुँह हमने सुनी कहानी थी। खूब ललड़ी मर््ददानी वव ह तो झाँसी वव ालली रानी थी॥$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('51afd93e-d60c-48a8-8f18-de997f957fde', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इनकी गाथा छोड़ चलेें हम झाँसी के मैदानों में, जहाँ खड़ी है ललक्मीबाई मर््द बनी मर््दानोों में, लेफ्ट‍ ‍िनेंट ववॉकर आ पहुँचा, आगे बढ़ा जववानों में,$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('f1789b05-1fb1-41d4-8fb5-9a4c92ab4c11', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$रानी ने तलववार खींच लली, हुआ द्वंद्व असमानों में, जख्मी होकर ववॉकर भागा, उसे अजब हैरानी थी। बुंदेलले हरबोलोों के मुँह हमने सुनी कहानी थी। खूब ललड़ी मर््ददानी वव ह तो झाँसी वव ालली रानी थी॥$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('452fc27a-09ad-444b-9ca7-4af1d245f34d', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$रानी बढ़ी काललपी आई, कर सौ मीलल निरंतर पार घोड़ा थक कर गिरा भूमि पर, गया स््वर््ग तत््ककालल सिधार, यमुना-तट पर अंग्रेजों ने फिर खाई रानी से हार,$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('61490e2b-81fb-45ab-bcc3-3e769b923ae8', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$विजयी रानी आगे चलल दी, किया ग््ववालियर पर अधिकार, बुंदेलले हरबालोों के मुँह हमने सुनी कहानी थी। खूब ललड़ी मर््ददानी वव ह तो झाँसी वव ालली रानी थी॥$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('a3d6986a-2819-4d8c-91fd-21e9de382f2e', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इस स््वतंत्रता-महायज्ञ में कई ववीरववर आए काम नाना धुंधूपंत, ताँतिया, चतुर अज़ीमुल््ला सरनाम, अहमद शाह मौलववी, ठाकुर कुँववरसिंह सैनिक अभिराम, भारत के इतिहास-गगन में अमर रहेंगे जिनके नाम, लेकिन आज जुर्म कहललाती उनकी जो कुरबानी थी। बुंदेलले हरबालोों के मुँह हमने सुनी कहानी थी। खूब ललड़ी मर््ददानी वव ह तो झाँसी वव ालली रानी थी॥ इनकी गाथा छोड़ चलेें हम झाँसी के मैदानों में, जहाँ खड़ी है ललक्मीबाई मर््द बनी मर््दानोों में, लेफ्ट‍ ‍िनेंट ववॉकर आ पहुँचा, आगे बढ़ा जववानों में, रानी ने तलववार खींच लली, हुआ द्वंद्व असमानों में, जख्मी होकर ववॉकर भागा, उसे अजब हैरानी थी। बुंदेलले हरबोलोों के मुँह हमने सुनी कहानी थी। खूब ललड़ी मर््ददानी वव ह तो झाँसी वव ालली रानी थी॥ रानी बढ़ी काललपी आई, कर सौ मीलल निरंतर पार घोड़ा थक कर गिरा भूमि पर, गया स््वर््ग तत््ककालल सिधार, यमुना-तट पर अंग्रेजों ने फिर खाई रानी से हार, विजयी रानी आगे चलल दी, किया ग््ववालियर पर अधिकार,$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('110c5417-3305-4543-be5e-4ab3c53b1c33', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अंग्रेजों के मित्र सिंधियाा ने छोड़ी रजधाानी थी। बुंदेले हरबोलों के मुँह हमने सुनी कहाानी थी। खूब लड़़ी मर््दानी वह तो झााँसी वााली राानी थी॥$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('4a2d8d94-749f-4e6f-ad0f-b537fb003729', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$विजय मिली, पर अंग्रेजों की फिर सेनाा घिर आई थी, अबके जनरल स््ममिथ सन्मुख थाा, उसने मुँह की खााई थी,$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('902c0d8b-b1ea-4203-9ffa-98c7d926dd31', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$काानाा और मंदराा सखियााँ राानी के सँग आई थीं, युद्ध क्ेत्र में उन दोनों ने भाारी माार मचााई थी,$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('79f93ae9-d13f-4c6c-931f-705b9064fe5d', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पर, पीछे ह्ू रोज आ गयाा, हााय! घिरी अब राानी थी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e37cd0db-0098-43b8-b44d-71a91414c170', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$तो भी राानी माार-काटकर चलती बनी सैन्य के पाार,$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
