  ('17e11416-8072-4a8c-b185-4b26a2e594bc', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$विजय मिली, पर अंग्रेजों की फिर सेनाा घिर आई थी, अबके जनरल स््ममिथ सन्मुख थाा, उसने मुँह की खााई थी, काानाा और मंदराा सखियााँ राानी के सँग आई थीं, युद्ध क्ेत्र में उन दोनों ने भाारी माार मचााई थी,$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('af81ee16-e6a3-4cb7-9693-c44d6c1d1d0b', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पर, पीछे ह्ू रोज आ गयाा, हााय! घिरी अब राानी थी। बुंदेले हरबोलों के मुँह हमने सुनी कहाानी थी। खूब लड़़ी मर््दानी वह तो झााँसी वााली राानी थी॥$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('c44e0730-4444-4ddf-8af0-79f151ec45d3', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$तो भी राानी माार-काटकर चलती बनी सैन्य के पाार, किंतु साामने नाालाा आयाा, थाा यह संकट विषम अपाार, घोड़़ाा अड़़ाा, नयाा घोड़़ाा थाा, इतने में आ गए सवाार,$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('09e10375-d9e0-4dbd-ad90-cc1f29680ea2', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$राानी एक, शत्रु बहुतेरे, होने लगे वाार पर वाार, घाायल होकर गिरी सिंहनी उसे वीर-गति पाानी थी। बुंदेले हरबोलों के मुँह हमने सुनी कहाानी थी। खूब लड़़ी मर््दानी वह तो झााँसी वााली राानी थी॥$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('8180df73-fa11-44bc-b42a-457cca10562e', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$राानी गई सिधाार, चिताा अब उसकी दिव्य सवाारी थी, मिलाा तेज से तेज, तेज की वह सच्ची अधिकाारी थी, अभी उम्र कुल तेइस की थी, मनुज नहीं अवताारी थी, हमको जीवित करने आई बन स्वतंत्रताा नाारी थी, दिखाा गई पथ, सिखाा गई हमको जो सीख सिखाानी थी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('ef99537b-cdff-45f8-8821-bf34df489868', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जााओ राानी यााद रखेंगे हम कृतज्ञ भाारत वाासी, यह तेराा बलिदाान जगाावेगाा स्वतंत्रताा अविनााशी, होवे चुप इतिहाास, लगे सच््चचााई को चााहे फााँसी, हो मदमााती विजय, मिटाा दे गोलों से चााहे झााँसी, तेराा स््ममाारक तू ही होगी, तू खुद अमिट निशाानी थी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('f8ffc44f-82db-4215-b505-ae74d800f503', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'd779da95-23e1-4ff4-9328-858f9c0068ba', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$राानी गई सिधाार, चिताा अब उसकी दिव्य सवाारी थी, मिलाा तेज से तेज, तेज की वह सच्ची अधिकाारी थी, अभी उम्र कुल तेइस की थी, मनुज नहीं अवताारी थी, हमको जीवित करने आई बन स्वतंत्रताा नाारी थी, दिखाा गई पथ, सिखाा गई हमको जो सीख सिखाानी थी। बुंदेले हरबोलों के मुँह हमने सुनी कहाानी थी। खूब लड़़ी मर््दानी वह तो झााँसी वााली राानी थी॥$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-149Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
